// חישוב השעות התפוסות והפנויות מתוך אירועי יומן גוגל
const events = $input.all();
const busySlotsByDate = {};

for (const ev of events) {
  const startStr = ev.json.start?.dateTime || ev.json.start?.date;
  const endStr = ev.json.end?.dateTime || ev.json.end?.date;

  if (!startStr) continue;

  const start = new Date(startStr);
  const dateKey = start.toISOString().split('T')[0];
  const hourKey = String(start.getHours()).padStart(2, '0') + ':00';

  if (!busySlotsByDate[dateKey]) {
    busySlotsByDate[dateKey] = [];
  }
  busySlotsByDate[dateKey].push(hourKey);
}

// הגדרת כלל שעות העבודה האפשריות (בדידות)
const standardWorkingHours = [
  "09:00", "10:00", "11:00", "12:00",
  "14:00", "15:00", "16:00", "17:00", "18:00", "19:00"
];

// הפקת מפת שעות פנויות מעודכנת
const availableSlots = {};
const today = new Date();

for (let i = 0; i < 7; i++) {
  const d = new Date(today);
  d.setDate(today.getDate() + i);
  const dateKey = d.toISOString().split('T')[0];
  const busyForDay = busySlotsByDate[dateKey] || [];

  availableSlots[dateKey] = standardWorkingHours.filter(h => !busyForDay.includes(h));
}

return [{
  json: {
    syncedAt: new Date().toISOString(),
    ownerEmail: 'segevshmueli0@gmail.com',
    availableSlotsMap: availableSlots
  }
}];
